//! Golden tests for aberration detection (CD-10) against R's `surveillance`
//! package (version 1.26.1, R 4.3.3).
//!
//! Reference values: `tests/fixtures/aberration.json`, generated by
//! `tests/fixtures/generators/aberration.R` (see that script for exactly how
//! each value was produced):
//! * EARS C1 and C2 upper bounds and alarms from `surveillance::earsC` with
//!   alpha = 1 − Φ(3) (the classic 3-SD threshold);
//! * EARS C3 from the published definition, computed in the R script from
//!   the C2 statistics (`earsC`'s own C3 bound omits the current period);
//! * CUSUM values, bounds, and alarms from `surveillance::algo.cusum`;
//! * Farrington-type upper bounds, expected counts, p-values, overdispersion,
//!   trend use, and alarms from `surveillance::farringtonFlexible`.

use phn_epi::aberration::{
    CusumParams, EarsMethod, EarsParams, FarringtonParams, ThresholdMethod, cusum, ears, farrington,
};
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/aberration.json")).unwrap()
}

fn nums(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap_or(f64::NAN))
        .collect()
}

fn bools(v: &Value) -> Vec<bool> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_bool().unwrap_or(false))
        .collect()
}

fn close(a: f64, b: f64, tol: f64) -> bool {
    if a.is_nan() || b.is_nan() {
        return a.is_nan() && b.is_nan();
    }
    (a - b).abs() <= tol * (1.0 + b.abs())
}

#[test]
fn ears_c1_c2_match_surveillance_and_c3_matches_definition() {
    let f = fixture();
    let counts = nums(&f["ears"]["counts"]);
    for (name, method) in [("C1", EarsMethod::C1), ("C2", EarsMethod::C2)] {
        let m = &f["ears"]["methods"][name];
        let r = ears(&counts, method, &EarsParams::classic(method)).unwrap();
        let ub = nums(&m["upperbound"]);
        let alarm = bools(&m["alarm"]);
        assert_eq!(r.len(), ub.len(), "{name}");
        assert_eq!(r[0].index as u64, m["first_index0"].as_u64().unwrap());
        for (i, p) in r.iter().enumerate() {
            match p.upper_bound {
                Some(u) => assert!(close(u, ub[i], 1e-9), "{name} {i}: {u} vs {}", ub[i]),
                None => assert!(ub[i].is_nan()),
            }
            // R signals when observed > bound; with a flat baseline (sd 0)
            // R's bound equals the mean and our statistic is ±∞ or 0.
            assert_eq!(p.alarm, alarm[i], "{name} alarm at {}", p.index);
        }
    }
    let m = &f["ears"]["methods"]["C3"];
    let r = ears(
        &counts,
        EarsMethod::C3,
        &EarsParams::classic(EarsMethod::C3),
    )
    .unwrap();
    let stat = nums(&m["statistic"]);
    let alarm = bools(&m["alarm"]);
    assert_eq!(r.len(), stat.len());
    for (i, p) in r.iter().enumerate() {
        if stat[i] >= 1e299 {
            assert!(p.statistic.is_infinite());
        } else {
            assert!(close(p.statistic, stat[i], 1e-9), "C3 {i}");
        }
        assert_eq!(p.alarm, alarm[i], "C3 alarm at {}", p.index);
    }
    assert!(r.iter().filter(|p| p.alarm).count() >= 2);
}

#[test]
fn cusum_matches_surveillance_algo_cusum() {
    let f = fixture();
    let counts = nums(&f["cusum"]["counts"]);
    for c in f["cusum"]["configs"].as_array().unwrap() {
        let r = cusum(
            &counts,
            &CusumParams {
                k: c["k"].as_f64().unwrap(),
                h: c["h"].as_f64().unwrap(),
                baseline_periods: c["baseline_periods"].as_u64().unwrap() as usize,
                mean: None,
                reset: c["reset"].as_bool().unwrap(),
            },
        )
        .unwrap();
        assert!(close(r.mean, c["mean"].as_f64().unwrap(), 1e-12));
        let cs = nums(&c["cusum"]);
        let ub = nums(&c["upperbound"]);
        let alarm = bools(&c["alarm"]);
        assert_eq!(r.points.len(), cs.len());
        for (i, p) in r.points.iter().enumerate() {
            assert!(
                close(p.cusum, cs[i], 1e-9),
                "cusum {i}: {} vs {}",
                p.cusum,
                cs[i]
            );
            assert!(close(p.upper_bound, ub[i], 1e-9), "bound {i}");
            assert_eq!(p.alarm, alarm[i], "alarm {i}");
        }
    }
}

#[test]
fn farrington_flexible_matches_surveillance() {
    let f = fixture();
    let counts = nums(&f["farrington"]["counts"]);
    let configs = f["farrington"]["configs"].as_object().unwrap();
    assert_eq!(configs.len(), 4);
    for (name, c) in configs {
        let pr = &c["params"];
        let method = match pr["thresholdMethod"].as_str().unwrap() {
            "nbPlugin" => ThresholdMethod::NbPlugin,
            "muan" => ThresholdMethod::Muan,
            _ => ThresholdMethod::Delta,
        };
        let limit = nums(&pr["limit54"]);
        let params = FarringtonParams {
            freq: 52,
            b: pr["b"].as_u64().unwrap() as usize,
            w: pr["w"].as_u64().unwrap() as usize,
            reweight: pr["reweight"].as_bool().unwrap(),
            weights_threshold: pr["weightsThreshold"].as_f64().unwrap(),
            alpha: pr["alpha"].as_f64().unwrap(),
            trend: pr["trend"].as_bool().unwrap(),
            p_threshold_trend: pr["pThresholdTrend"].as_f64().unwrap(),
            limit_cases: limit[0],
            limit_periods: limit[1] as usize,
            no_periods: pr["noPeriods"].as_u64().unwrap() as usize,
            past_periods_not_included: pr["pastWeeksNotIncluded"].as_u64().unwrap() as usize,
            threshold_method: method,
        };
        let first = c["range_first_index0"].as_u64().unwrap() as usize;
        let r = farrington(&counts, &params, Some(first..counts.len())).unwrap();
        let ub = nums(&c["upperbound"]);
        let exp = nums(&c["expected"]);
        let pv = nums(&c["pvalue"]);
        let tr = nums(&c["trend"]);
        let phi = nums(&c["phi"]);
        let alarm = bools(&c["alarm"]);
        assert_eq!(r.len(), ub.len());
        for (i, p) in r.iter().enumerate() {
            let ctx = format!("{name} period {}", p.index);
            assert!(
                close(p.phi, phi[i], 1e-6),
                "{ctx}: phi {} vs {}",
                p.phi,
                phi[i]
            );
            assert_eq!(p.trend, tr[i] == 1.0, "{ctx}: trend");
            match p.upper_bound {
                Some(u) => assert!(close(u, ub[i], 1e-6), "{ctx}: bound {u} vs {}", ub[i]),
                None => assert!(ub[i].is_nan(), "{ctx}: R has bound {}", ub[i]),
            }
            if let Some(e) = p.expected {
                assert!(close(e, exp[i], 1e-6), "{ctx}: expected {e} vs {}", exp[i]);
            }
            if let Some(q) = p.p_value {
                assert!(close(q, pv[i], 1e-6), "{ctx}: p {q} vs {}", pv[i]);
            }
            assert_eq!(p.alarm, alarm[i], "{ctx}: alarm");
        }
        assert!(r.iter().any(|p| p.alarm), "{name} should signal somewhere");
    }
}
